/* 第二优先交互原型：只替换当前会话的展示，不写入模拟记录、不调用业务服务。 */
'use strict';
(()=>{
 const catalog={tool:['工具与子调用',['运行中','成功','失败','已中断','缺调用','空结果','未知媒体']],process:['过程与收尾',['运行中','完成折叠','失败无答案','已停止','指标缺失']],retry:['错误与重试',['等待重试','重试开始','已取消','重试耗尽','输出截断']],history:['历史分页',['手动加载','自动加载','加载中','加载失败','没有更多']],queue:['队列与引导',['待提交','已接受','引导竞争失败','停止后保留']],pressure:['上下文与压缩',['自动压缩','手动执行中','手动失败','手动完成','摘要缺窗','暂无估算','模型切换']],command:['命令与斜杠',['候选就绪','无会话','加载中','没有匹配','目录失败','参数提示']]};
 let active=null,selection=0,historyPages=0;
 // 工作台能力预览接管时释放诊断预览，退出后回到真实原型草稿。
 document.addEventListener('qs-prototype-leave-diagnostics',()=>{active=null;});
 const originalRender=renderApp,originalMenu=systemDemoMenu;
 const key=()=>`${state.workspace}/${ws().current||'new'}`;
 const buttons=items=>`<div class="p2-actions">${items.map(([action,label])=>`<button class="btn" type="button" data-p2="${action}">${label}</button>`).join('')}</div>`;
 const details=(title,body,open=false)=>`<details ${open?'open':''}><summary>${title}</summary>${body}</details>`;
 // 入口与原审批、提问演示同级；退出时原有草稿和会话内容仍由原工作台拥有。
 systemDemoMenu=function(){return originalMenu()+`<h3 class="system-menu-title">第二优先 · 转写与诊断</h3><div class="modal-list">${Object.entries(catalog).map(([id,[title]])=>`<button class="choice-row" data-p2-open="${id}">${icon('chat')}<span><strong>${title}</strong><small>在当前工作台内查看状态与恢复操作</small></span>${icon('next')}</button>`).join('')}</div>`;};
 function content(){const {group,mode}=active;let html='<p class="p2-muted">本地交互原型 · 以下数据仅用于界面评审，不执行命令或修改真实文件。</p>';
 if(group==='tool'){
 html+=`<article class="p2-card ${mode==='失败'?'p2-error':''}"><span class="tag">${mode}</span><h2>检查 3 号泵配置</h2><p>${({'缺调用':'调用参数不在已加载历史中，工具名称与耗时暂不可知。','空结果':'工具已返回，暂无可展示的文本结果。','已中断':'已收到中断记录，保留中断前输出。','失败':'执行失败，部分输出已保留；不会自动重新执行。','未知媒体':'此内容类型暂不支持内嵌展示，仅提供安全文本说明。'})[mode]||'读取配置并核对维护记录。展开查看调用参数与输出。'}</p>${mode==='缺调用'?buttons([['older-tool','查看更早历史']]):''}</article>`;
 if(!['缺调用','空结果','未知媒体'].includes(mode))html+=details('工具调用 · 2 个子调用',details('read · 配置片段','<pre>路径：workspace/pump.json\n行范围：1–20\n温度阈值：85 °C</pre>'.replace(/\n/g,'<br>'),true)+details('bash / pwsh · 命令与输出',`<pre>${esc('Get-Content D:/workspace/'+ 'long-directory/'.repeat(12)+'pump.json\n输出：读取完成')}</pre>`),true);
 html+=details('write / edit · 独立展示样例','<p>目标：workspace/pump.json · 修改前后对照（演示）</p><pre>- threshold: 85\n+ threshold: 90</pre><p>结果以实际工具记录为准，卡片不提供再次执行操作。</p>');
 // 八类官方工具子呈现逐类可展开；提问历史只读，不在工具卡创建第二个回答表单。
 html+=details('read-image · 图片读取','<img class="wb-image" src="factory.svg" alt="设备读取结果示意图"><p>本地示意图；真实媒体不可用时保留说明。</p>');
 html+=details('search · 搜索结果','<ul><li>pump.json:12 · threshold: 85</li><li>maintenance.md:8 · 冷却回路待复核</li></ul><p>路径与行号定位需真实资源身份；原型不打开本机文件。</p>');
 html+=details('web · 来源摘要','<blockquote>来源标题：设备维护说明<br>摘要：核对过滤器压差与冷却流量。</blockquote><p>离线样本，未知协议不生成可点击链接。</p>');
 html+=details('todo · 待办清单','<ul><li>已完成：读取配置</li><li>进行中：核对维护记录</li><li>待处理：现场复核</li></ul>');
 html+=details('ask-question · 历史回答','<p>问题：检查哪个范围？</p><p>已回答：冷却回路</p><p>未回答时仅定位当前待回答区，不复制可提交表单。</p>');
 if(mode==='未知媒体')html+=`<pre>${esc('<img src=x onerror=alert(1)>')}</pre>`;
 }
 if(group==='process')html+=`<article class="p2-card"><span class="tag">${mode}</span><h2>第 2 轮 · 步骤 3</h2><p>${mode==='运行中'?'2 个工具正在处理：读取配置、检索记录。':mode==='失败无答案'?'本轮失败，未生成最终答案。':mode==='已停止'?'本轮已停止，部分输出保留。':'本轮处理结束。'}</p></article>${details('处理过程','<p>步骤 1：读取配置</p><p>步骤 2：核对维护记录</p><p>步骤 3：整理结论</p>',mode==='运行中')}<p>${mode==='完成折叠'?'建议优先检查冷却回路。':''}</p><p class="p2-muted">${mode==='指标缺失'?'耗时与 token 指标暂无数据。':'4.2 秒 · 输入 1,240 / 输出 210 token（模拟统计）'}</p>`;
 if(group==='retry')html+=`<article class="p2-card p2-error"><span class="tag">${mode}</span><h2>${mode==='输出截断'?'输出达到长度限制':'模型请求诊断'}</h2><p>部分回答：3 号泵温度上升，需要结合维护记录…</p><p>${({'等待重试':'第 2 次重试已排期，等待服务开始；不以本地倒计时触发发送。','重试开始':'第 2 次请求已开始。','已取消':'自动重试已取消。','重试耗尽':'重试次数已耗尽，请检查连接后继续提问。','输出截断':'本次回答不完整，可补充要求继续对话。'})[mode]}</p>${details('查看原因','<pre>模拟诊断：请求超时 / 输出长度限制。</pre>')}</article>`;
 if(group==='history')html+=`<p>向上浏览历史；失败暂停自动加载，保留手动重试。</p><div class="p2-history" tabindex="0" aria-label="历史分页预览"><div id="p2-history-top"></div><article id="p2-anchor" class="p2-card">已加载消息：检查设备温度</article>${details('展开历史工具输出','<pre>温度：86 °C\n冷却回路：待复核</pre>')}<article class="p2-card">已有回答：建议核查冷却回路。</article><article class="p2-card">最近消息：请继续分析。</article></div>`;
 if(group==='queue')html+=`<article class="p2-card"><span class="tag">${mode}</span><h2>下一条消息</h2><label for="p2-queue">待发内容</label><input id="p2-queue" class="p2-input" value="继续检查冷却回路">${buttons([['save-queue','保存编辑'],['remove-queue','移除'],['steer','引导当前轮']])}<p>${mode==='引导竞争失败'?'当前轮已结束，引导失败，消息保留在队列。':mode==='停止后保留'?'当前轮停止不等于清空队列，已接受消息仍可能继续执行。':'待发消息尚未作为当前轮的用户消息落地。'}</p></article><p class="p2-muted">完整发送、停止和自动消费沿用“交互演示 → 发送与恢复”。</p>`;
 if(group==='pressure')html+=`<article class="p2-card"><h2>上下文压力</h2>${['暂无估算','模型切换'].includes(mode)?'<p>暂无有效估算；等待当前模型的新样本，不限制发送。</p>':'<p>约 24,000 / 64,000 token · 38%（估算）</p><progress value="24000" max="64000" aria-label="上下文估算占用"></progress>'}${details('查看组成','<p>系统与指令约 4k，历史与工具约 18k，当前输入约 2k。启发式分类不保证精确加总，不代表计费。</p>')}</article><article class="p2-card"><span class="tag">${mode}</span><h2>上下文压缩</h2><p>${({'自动压缩':'自动摘要已落地。','手动执行中':'正在整理摘要，尚未收到完成记录。','手动失败':'压缩失败，原历史保持可读。','手动完成':'命令已完成并关联摘要，只展示一次结果。','摘要缺窗':'摘要正文不在当前历史窗口，可向前加载。'})[mode]||'等待可用压缩记录。'}</p>${details('查看摘要',mode==='摘要缺窗'?'<p>正文暂不可用。</p>':'<p>已检查 3 号泵，待复核冷却回路。（模拟摘要）</p>')}</article>`;
 if(group==='command')html+='<article class="p2-card"><h2>命令发现与执行结果</h2><p>在下方输入区键入 /。支持上下选择、Enter / Tab 确认和 Esc 关闭；中文输入法组合期间不执行。</p><p>演示 /compact 的范围选择、风险确认及执行失败。取消保留草稿，失败保留历史。</p></article>';
 return html+'<p id="p2-status" role="status" aria-live="polite"></p>';
 }
 function decorate(){if(!active||active.key!==key()||!$('.center'))return;const {group,mode}=active;
 $('.center').insertAdjacentHTML('afterbegin',`<div class="p2-bar"><label>第二优先 <select id="p2-group" aria-label="第二优先场景">${Object.entries(catalog).map(([id,[title]])=>`<option value="${id}" ${id===group?'selected':''}>${title}</option>`).join('')}</select></label><label>状态 <select id="p2-mode" aria-label="演示状态">${catalog[group][1].map(v=>`<option ${v===mode?'selected':''}>${v}</option>`).join('')}</select></label><button class="text-button" data-p2="exit">退出预览</button></div>`);
 $('#center-scroll').innerHTML=`<div class="p2-content">${content()}</div>`;
 // 新会话的输入原在欢迎区内；切成诊断视图后补回同一底部容器。
 if(!$('.composer-shell'))$('.center-footer').insertAdjacentHTML('beforebegin','<div class="chat-composer"><div class="composer-shell"></div></div>');
 // 独立预览输入不覆盖原始草稿，也不走全局 send；退出预览会重新呈现原 composer。
 $('.composer-shell').innerHTML=group==='command'?'<div class="composer p2-composer"><label for="p2-command">命令输入 · 本地演示</label><input id="p2-command" class="p2-input" role="combobox" aria-label="命令输入" aria-controls="p2-menu" aria-expanded="false" aria-autocomplete="list" value="/"><ul id="p2-menu" class="p2-menu" role="listbox" aria-label="命令候选"></ul><p id="p2-hint" class="p2-muted"></p></div>':'<p class="p2-muted">正在预览第二优先状态；退出预览后可继续原会话输入。</p>';
 if(group==='history'){historyPages=0;historyTop();$('.p2-history').scrollTop=110;$('.p2-history').onscroll=()=>{if(active?.mode==='自动加载'&&$('.p2-history').scrollTop<10)loadHistory();};}
 if(group==='command')menu();
 }
 renderApp=function(){originalRender();decorate();};
 function start(group){resetSystemDemo();active={group,mode:catalog[group][1][0],key:key()};selection=0;closeModal();renderApp();}
 function historyTop(){const mode=active.mode;$('#p2-history-top').innerHTML=mode==='加载中'?'<p role="status">正在加载早期记录…</p>':mode==='没有更多'||historyPages>=2?'<p>已到最早记录</p>':`<p>${mode==='加载失败'?'加载失败，自动加载已暂停。':'可查看更早的记录。'}</p>${buttons([['load',mode==='加载失败'?'重试加载':'加载更早消息']])}`;}
 function loadHistory(){if(historyPages>=2)return;const box=$('.p2-history'),height=box.scrollHeight,top=box.scrollTop;const row=document.createElement('article');row.className='p2-card';row.textContent=`更早的消息 · 第 ${++historyPages} 页`;$('#p2-history-top').after(row);if(active.mode==='加载失败')active.mode='手动加载';historyTop();box.scrollTop=top+box.scrollHeight-height;$('#p2-status').textContent='已加载，保持原阅读位置。';}
 // 不同命令分别展示 Host 执行、选择弹层与会话反馈，不把命令目录等同单一确认框。
 const commands=[['/compact','压缩上下文 · 需要确认'],['/help','查看命令说明'],['/model','选择当前会话模型'],['/feedback','当前会话反馈']];
 function menu(){const field=$('#p2-command'),mode=active.mode,hint=({'无会话':'请先选择会话，不会因输入 / 自动创建会话。','加载中':'目录加载中…','没有匹配':'没有匹配的命令。','目录失败':'目录不可用，不执行猜测命令。','参数提示':'/compact [范围] · 参数由命令服务校验。'})[mode];const list=hint?[]:commands.filter(c=>c[0].startsWith(field.value));selection=Math.min(selection,Math.max(0,list.length-1));$('#p2-menu').innerHTML=list.map((c,i)=>`<li role="option" id="p2-option-${i}" aria-selected="${i===selection}" data-p2-command="${c[0]}">${c[0]} · ${c[1]}</li>`).join('');$('#p2-menu').hidden=!list.length;field.setAttribute('aria-expanded',String(!!list.length));if(list.length)field.setAttribute('aria-activedescendant',`p2-option-${selection}`);else field.removeAttribute('aria-activedescendant');$('#p2-hint').textContent=hint||(!list.length?'没有匹配的命令。':'候选仅为模拟数据，不代表正式目录。');if(mode==='目录失败')$('#p2-hint').insertAdjacentHTML('beforeend',buttons([['catalog-retry','重试目录']]));}
 function pick(command){if(command==='/help'){$('#p2-status').textContent='命令说明已显示（模拟），未请求真实服务。';return;}if(command==='/model'){openModal('选择模型',`<p>目标：当前演示会话。弹层未结算时冻结界面切换，不影响后台运行。</p><label>模型<select><option>deepseek-chat</option><option>deepseek-reasoner</option></select></label>${buttons([['cancel','取消'],['model-done','确认选择（模拟）']])}`);return;}if(command==='/feedback'){openModal('会话反馈',`<p>反馈对象：session-demo；不携带消息 ID。</p><label>反馈说明<textarea id="p2-feedback-draft"></textarea></label>${buttons([['cancel','取消'],['feedback-fail','模拟提交失败']])}<p id="p2-feedback-error" role="alert"></p>`);return;}openModal('压缩上下文',`<p>压缩会减少后续模型可见的细节，原始历史保留。</p><label for="p2-scope">压缩范围</label><select id="p2-scope"><option>当前会话</option></select>${buttons([['cancel','取消'],['confirm','确认压缩（模拟）']])}`);}
 // 单独结算模型选择与反馈失败，失败不关闭弹层或清空已填内容。
 document.addEventListener('click',e=>{const action=e.target.closest('[data-p2]')?.dataset.p2;if(action==='model-done'){closeModal();$('#p2-status').textContent='模型已选择（模拟），只影响后续请求。';}if(action==='feedback-fail')$('#p2-feedback-error').textContent='提交失败，请重试；说明已保留。';});
 // 捕获阶段拦截仅属于本扩展的事件，避免 Enter 穿透到原工作台发送逻辑。
 document.addEventListener('keydown',e=>{if(e.target.id!=='p2-command')return;e.stopImmediatePropagation();if(e.isComposing||e.keyCode===229)return;const options=[...document.querySelectorAll('[data-p2-command]')];if(e.key==='Escape'){$('#p2-menu').hidden=true;e.target.setAttribute('aria-expanded','false');e.target.removeAttribute('aria-activedescendant');return;}if($('#p2-menu').hidden||!options.length)return;if(['ArrowDown','ArrowUp'].includes(e.key)){e.preventDefault();selection=(selection+(e.key==='ArrowDown'?1:-1)+options.length)%options.length;menu();}else if(['Enter','Tab'].includes(e.key)){e.preventDefault();pick(options[selection].dataset.p2Command);}},true);
 document.addEventListener('input',e=>{if(e.target.id==='p2-command'){selection=0;menu();}});
 document.addEventListener('change',e=>{if(e.target.id==='p2-group')start(e.target.value);if(e.target.id==='p2-mode'){active.mode=e.target.value;renderApp();}});
 $('#modal').addEventListener('close',()=>{if(active?.group==='command'&&active.key===key())$('#p2-command')?.focus();});
 document.addEventListener('click',e=>{const launch=e.target.closest('[data-p2-open]');if(launch){start(launch.dataset.p2Open);return;}const option=e.target.closest('[data-p2-command]');if(option){pick(option.dataset.p2Command);return;}const button=e.target.closest('[data-p2]');if(!button)return;switch(button.dataset.p2){case 'exit':active=null;renderApp();break;case 'older-tool':start('history');break;case 'load':loadHistory();break;case 'catalog-retry':active.mode='候选就绪';renderApp();$('#p2-command').focus();break;case 'save-queue':$('#p2-status').textContent='已保存模拟队列内容。';break;case 'remove-queue':button.closest('article').remove();$('#p2-status').textContent='已移除模拟队列消息。';break;case 'steer':$('#p2-status').textContent=active.mode==='已接受'?'已引导当前轮（模拟）。':'当前轮不可引导，消息仍保留在队列。';break;case 'cancel':closeModal();$('#p2-status').textContent='已取消，草稿保留。';break;case 'confirm':closeModal();$('#p2-status').textContent='压缩执行失败（模拟），原历史与草稿保留。';break;}});
})();
